// ─── Computation ────────────────────────────────────────────────────────────

function evalSeries(series: Term[][], tau: number): number {
  let result = 0;
  let tauPow = 1;
  for (const terms of series) {
    let s = 0;
    for (const [A, B, C] of terms) {
      s += A * Math.cos(B + C * tau);
    }
    result += s * tauPow;
    tauPow *= tau;
  }
  return result;
}

function norm2pi(x: number): number {
  const TWO_PI = 2 * Math.PI;
  return ((x % TWO_PI) + TWO_PI) % TWO_PI;
}

/**
 * Heliocentric ecliptic coordinates (ecliptic of date).
 * Returns [L (rad), B (rad), R (AU)].
 */
export function helioEcliptic(planet: string, jd: number): [number, number, number] {
  const tau = (jd - 2451545.0) / 365250.0;
  const data = VSOP_DATA[planet];
  if (!data) throw new Error("Unknown planet: " + planet);
  const L = norm2pi(evalSeries(data.L, tau));
  const B = evalSeries(data.B, tau);
  const R = evalSeries(data.R, tau);
  return [L, B, R];
}

/**
 * Geocentric apparent ecliptic longitude of the Sun (degrees).
 */
export function vsop87SunLongitude(jd: number): number {
  const [Le, _Be, _Re] = helioEcliptic('earth', jd);
  let sunLon = norm2pi(Le + Math.PI);
  // Aberration (Meeus Ch. 25)
  const tau = (jd - 2451545.0) / 365250.0;
  const kappa = (20.49552 / 3600) * (Math.PI / 180);
  sunLon -= kappa;
  // FK5 correction (Meeus p. 166)
  const Lp = sunLon - (1.397 * Math.PI / 180) * tau - (0.00031 * Math.PI / 180) * tau * tau;
  sunLon += (-0.09033 / 3600) * (Math.PI / 180)
           + (0.03916 / 3600) * (Math.PI / 180) * (Math.cos(Lp) + Math.sin(Lp));
  return ((sunLon * 180 / Math.PI) % 360 + 360) % 360;
}

/**
 * Geocentric apparent ecliptic longitude of a planet (degrees).
 * Includes light-time iteration, aberration, and FK5 correction.
 */
export function vsop87PlanetLongitude(planet: string, jd: number): number {
  const [Le, Be, Re] = helioEcliptic('earth', jd);
  const xe = Re * Math.cos(Be) * Math.cos(Le);
  const ye = Re * Math.cos(Be) * Math.sin(Le);
  const ze = Re * Math.sin(Be);

  // Light-time iteration (3 passes)
  let tau_lt = 0;
  let lon = 0;
  let gLat = 0;
  for (let i = 0; i < 3; i++) {
    const [Lp, Bp, Rp] = helioEcliptic(planet, jd - tau_lt);
    const xp = Rp * Math.cos(Bp) * Math.cos(Lp);
    const yp = Rp * Math.cos(Bp) * Math.sin(Lp);
    const zp = Rp * Math.sin(Bp);
    const dx = xp - xe, dy = yp - ye, dz = zp - ze;
    const dist = Math.sqrt(dx * dx + dy * dy + dz * dz);
    tau_lt = dist * 0.0057755183; // days
    lon = Math.atan2(dy, dx);
    gLat = Math.atan2(dz, Math.sqrt(dx * dx + dy * dy));
  }

  // Aberration (Ron-Vondrak or simple annual)
  const sunLon = Le + Math.PI;
  const kappa = (20.49552 / 3600) * (Math.PI / 180);
  lon += -kappa * Math.cos(sunLon - lon) / Math.cos(gLat);

  // FK5 correction
  const tau = (jd - 2451545.0) / 365250.0;
  const Lp = lon - (1.397 * Math.PI / 180) * tau - (0.00031 * Math.PI / 180) * tau * tau;
  lon += (-0.09033 / 3600) * (Math.PI / 180)
       + (0.03916 / 3600) * (Math.PI / 180) * (Math.cos(Lp) + Math.sin(Lp));

  return ((lon * 180 / Math.PI) % 360 + 360) % 360;
}
